#!/usr/bin/env python3
"""R50 A2 · write the public ES/EN Home after legacy assembly."""
from __future__ import annotations
import argparse, html
from pathlib import Path
SOURCE=Path(__file__).resolve().parents[1]

def picker(en):
    if en:
        return '<section class="ig-audience" data-ig-audience-picker aria-labelledby="ig-audience-title"><p class="ig-audience-title" id="ig-audience-title">Content for… <span class="ig-audience-current" data-ig-audience-status>General</span></p><div class="ig-audience-options"><button type="button" data-ig-audience-stage="children" aria-pressed="false">Children</button><button type="button" data-ig-audience-stage="teenagers" aria-pressed="false">Teenagers</button><button type="button" data-ig-audience-stage="adults" aria-pressed="false">Adults</button><button type="button" data-ig-audience-stage="any" aria-pressed="false">Any age</button></div><p class="ig-audience-note">Choose a life stage if you want to adjust examples and content. If you do not choose one, you will see the general version. Your choice lasts only for this session.</p></section>'
    return '<section class="ig-audience" data-ig-audience-picker aria-labelledby="ig-audience-title"><p class="ig-audience-title" id="ig-audience-title">Contenido para… <span class="ig-audience-current" data-ig-audience-status>General</span></p><div class="ig-audience-options"><button type="button" data-ig-audience-stage="children" aria-pressed="false">Infancia</button><button type="button" data-ig-audience-stage="teenagers" aria-pressed="false">Adolescencia</button><button type="button" data-ig-audience-stage="adults" aria-pressed="false">Adultez</button><button type="button" data-ig-audience-stage="any" aria-pressed="false">Cualquier edad</button></div><p class="ig-audience-note">Elige una etapa si quieres ajustar los ejemplos y el contenido. Si no eliges ninguna, verás la versión general. La elección dura solo esta sesión.</p></section>'

def render(root,lang):
    en=lang=='en';prefix='/en/' if en else '/'
    title='Iris Green · Clear information and practical tools' if en else 'Iris Green · Información clara y herramientas prácticas'
    meta='Clear information, practical resources and tools for everyday situations.' if en else 'Información clara, recursos prácticos y herramientas para situaciones del día a día.'
    lead='Find information, resources and tools for everyday situations.' if en else 'Busca información, recursos y herramientas para situaciones del día a día.'
    areas=[
    ('/en/neurodiversity/conditions/' if en else '/es/neurodiversidad/condiciones/','Conditions' if en else 'Condiciones','Read clear explanations about different conditions.' if en else 'Consulta explicaciones claras sobre diferentes condiciones.'),
    ('/en/situations/' if en else '/es/situaciones/','Situations' if en else 'Situaciones','Find information starting from a specific situation.' if en else 'Encuentra información a partir de una situación concreta.'),
    ('/en/everyday-life/' if en else '/es/biblioteca/','Everyday life' if en else 'Vida diaria','Find ideas and support for studying, working, getting organised and looking after yourself.' if en else 'Encuentra ideas y apoyos para estudiar, trabajar, organizarte y cuidarte.'),
    ('/es/investigacion/?lang=en' if en else '/es/investigacion/','Research' if en else 'Investigación','Read studies explained with their results and limitations.' if en else 'Consulta estudios explicados con sus resultados y límites.'),
    ('/en/data/' if en else '/es/datos/','Data' if en else 'Datos','Check figures with their source, population and date.' if en else 'Consulta cifras con su fuente, población y fecha.'),
    ('/es/tramites/directorio/?lang=en' if en else '/es/tramites/directorio/','Support and procedures' if en else 'Ayudas y trámites','Find support, rights and procedures based on where you live.' if en else 'Busca apoyos, derechos y trámites según el lugar donde vives.'),
    ('/en/resources/' if en else '/es/recursos/','Resources and games' if en else 'Recursos y juegos','Use visual routines, games and practical tools.' if en else 'Usa rutinas visuales, juegos y herramientas prácticas.'),
    ('/en/interests/' if en else '/es/intereses/','Your interests' if en else 'Tus intereses','Explore a topic and go deeper at your own pace.' if en else 'Explora un tema y profundiza a tu ritmo.'),
    ('/en/workshop/' if en else '/es/taller/','The workshop' if en else 'El taller','Create, test and develop your own projects.' if en else 'Crea, prueba y desarrolla tus propios proyectos.'),
    ('/en/quiet-space/' if en else '/es/sitio-tranquilo/','Quiet space' if en else 'Rincón tranquilo','Choose breathing, landscapes or an immersive experience.' if en else 'Elige respiración, paisajes o una experiencia inmersiva.')]
    areas_html=''.join(f'<a class="ig-home-area" href="{u}"><strong>{html.escape(t)}</strong><span>{html.escape(d)}</span></a>' for u,t,d in areas)
    sabik=(SOURCE/'sabik/iris-panel.html').read_text(encoding='utf-8')
    search_title='What are you looking for?' if en else '¿Qué estás buscando?'
    ph='For example: noise, sleep, transport or studying' if en else 'Por ejemplo: ruido, dormir, transporte o estudiar'
    search='Search' if en else 'Buscar';areas_title='Choose where to start' if en else 'Elige por dónde empezar'
    accessibility='Accessibility' if en else 'Accesibilidad';music='Music' if en else 'Música';close='Close' if en else 'Cerrar'
    panel_title='Accessibility and reading' if en else 'Accesibilidad y lectura'
    page=f'''<!doctype html><html lang="{lang}"><head><script src="/assets/preferencias-lectura.js"></script><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(meta)}"><meta property="og:description" content="{html.escape(meta)}"><link rel="canonical" href="https://irisgreen.eu{prefix}"><link rel="alternate" hreflang="es" href="https://irisgreen.eu/"><link rel="alternate" hreflang="en" href="https://irisgreen.eu/en/"><link rel="alternate" hreflang="x-default" href="https://irisgreen.eu/"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&family=Atkinson+Hyperlegible:wght@400;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/ig-r42-materials.css"><link rel="stylesheet" href="/assets/ig-audience.css"><link rel="stylesheet" href="/assets/home-r42-child-safe.css"><link rel="stylesheet" href="/sabik/iris-mount.css"><script src="/assets/ig-audience.js"></script><script defer src="/assets/buscador-comun.js"></script><script defer src="/assets/home-r42-child-safe.js"></script></head><body class="ig-home-r42" data-ig-materials="r42" data-ig-r42-family="home"><a class="ig-home-skip" href="#main">{'Skip to content' if en else 'Ir al contenido'}</a><header class="ig-home-header"><a class="ig-home-brand" href="{prefix}">Iris Green</a><div class="ig-home-tools"><button type="button" data-ig-home-settings-open data-ig-reading-trigger aria-controls="ig-home-settings" aria-expanded="false">{accessibility}</button><button type="button" data-ig-music aria-expanded="false">{music}</button><a class="ig-home-lang" href="{'/' if en else '/en/'}" lang="{'es' if en else 'en'}">{'ES' if en else 'EN'}</a></div></header><main id="main" class="ig-home-layout"><div class="ig-home-main"><section class="ig-home-hero"><p class="ig-home-eyebrow">{'Clear information and practical tools' if en else 'Información clara y herramientas prácticas'}</p><h1>{'Start with what you need.' if en else 'Empieza por lo que necesitas.'}</h1><p>{html.escape(lead)}</p>{picker(en)}</section><section class="ig-home-search-card"><h2>{search_title}</h2><form class="ig-home-search" data-ig-home-search role="search"><label class="ig-home-skip" for="ig-home-q">{search_title}</label><input id="ig-home-q" type="search" autocomplete="off" placeholder="{html.escape(ph)}"><button type="submit">{search}</button></form><div class="ig-home-suggestions" data-ig-home-suggestions></div><p class="ig-home-search-status" data-ig-home-search-status role="status" aria-live="polite"></p><div class="ig-home-results" data-ig-home-results></div></section><section class="ig-home-areas"><h2>{areas_title}</h2><div class="ig-home-area-grid">{areas_html}</div></section></div><aside class="ig-home-sabik-wrap" aria-label="Sabik"><h2>{'Ask Sabik' if en else 'Pregunta a Sabik'}</h2>{sabik}</aside></main><footer class="ig-home-footer"><span>Iris Green</span><nav><a href="{'/en/privacy/' if en else '/es/privacidad/'}">{'Privacy' if en else 'Privacidad'}</a><a href="/es/lectura-accesible/?lang={'en' if en else 'es'}">{'Accessibility and reading' if en else 'Accesibilidad y lectura'}</a><a href="/es/sobre-iris-green/?lang={'en' if en else 'es'}">{'About Iris Green' if en else 'Sobre Iris Green'}</a></nav></footer><dialog id="ig-home-settings" data-ig-reading-panel aria-labelledby="ig-home-settings-title"><div class="ig-home-settings-head"><h2 id="ig-home-settings-title">{panel_title}</h2><button type="button" data-ig-home-settings-close data-ig-reading-close aria-label="{close}">×</button></div><div class="ig-home-a11y-controls"><div class="ig-home-a11y-size"><span>{'Text size' if en else 'Tamaño del texto'}</span><button type="button" data-ig-home-pref="size-down">A−</button><output data-ig-home-pref-size aria-live="polite">100%</output><button type="button" data-ig-home-pref="size-up">A+</button></div><div class="ig-home-a11y-grid"><button type="button" data-ig-home-pref="spacing" aria-pressed="false">{'More spacing' if en else 'Más espaciado'}</button><button type="button" data-ig-home-pref="controls" aria-pressed="false">{'Bigger controls' if en else 'Controles más grandes'}</button><button type="button" data-ig-home-pref="contrast" aria-pressed="false">{'More contrast' if en else 'Más contraste'}</button><button type="button" data-ig-home-pref="guide" aria-pressed="false">{'Reading guide' if en else 'Guía de lectura'}</button><button type="button" data-ig-home-pref="motion" aria-pressed="false">{'Reduce motion' if en else 'Reducir movimiento'}</button><button type="button" data-ig-home-pref="speak" aria-pressed="false">{'Read this page' if en else 'Leer esta página'}</button></div><div data-ig-home-text-options></div><div data-ig-home-transparency-options></div><div class="ig-home-a11y-foot"><button type="button" data-ig-home-pref="reset">{'Reset' if en else 'Restablecer'}</button><a href="/es/lectura-accesible/?lang={'en' if en else 'es'}">{'More accessibility options' if en else 'Más opciones de accesibilidad'}</a></div></div></dialog><script defer src="/assets/interfaz-comun.js"></script><script defer src="/assets/musica.js"></script><script src="/sabik/sabik-motion-r37.js"></script><script src="/sabik/sabik-web-r01.js"></script><script src="/sabik/retrieval-panel.js"></script><script type="module" src="/sabik/iris-mount.mjs"></script></body></html>'''
    out=root if not en else root/'en';out.mkdir(parents=True,exist_ok=True);(out/'index.html').write_text(page,encoding='utf-8')

def sitemap(root):
    for name in ('sitemap.xml','sitemap-1.xml'):
        p=root/name
        if p.is_file():
            s=p.read_text(encoding='utf-8')
            if '<loc>https://irisgreen.eu/en/</loc>' not in s:s=s.replace('</urlset>','  <url>\n    <loc>https://irisgreen.eu/en/</loc>\n  </url>\n</urlset>')
            p.write_text(s,encoding='utf-8')
def main():
    ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,required=True);root=ap.parse_args().root.resolve();render(root,'es');render(root,'en');sitemap(root);print('R50 Home ES/EN written')
if __name__=='__main__':main()
